// Generates crates/sirene-core/src/math/symbols_data.rs from KaTeX's symbol table
// (spec/latex-resources.md, LRES-3). Development tool: the generated file is checked in.
//
// Setup (once): the KaTeX checkout described in scripts/katex-fixtures.mjs, at tag v0.19.1.
// Run:
//   node scripts/katex-symbols.mjs
//
// KaTeX's `src/symbols.ts` fills a map from each command or character to its atom group, its font
// (`main` or `ams`), and the character to draw. Node 24 reads the TypeScript directly, so this
// script imports that table instead of parsing the file. The Rust table holds the same entries
// in four byte-sorted slices (characters and control sequences, for math and text mode), so a
// lookup is a binary search. Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020 Khan
// Academy and other contributors; see THIRD-PARTY-NOTICES.

import { writeFileSync } from "node:fs";

const { default: symbols } = await import(
  new URL("../local/katex/src/symbols.ts", import.meta.url)
);

const GROUPS = {
  "accent-token": "Accent",
  bin: "Bin",
  close: "Close",
  inner: "Inner",
  mathord: "MathOrd",
  "op-token": "Op",
  open: "Open",
  punct: "Punct",
  rel: "Rel",
  spacing: "Spacing",
  textord: "TextOrd",
};
const FONTS = { main: "Main", ams: "Ams" };

function rustString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"' || ch === "\\") out += "\\" + ch;
    else if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += `\\u{${cp.toString(16)}}`;
  }
  return out + '"';
}

function byBytes(a, b) {
  return Buffer.compare(Buffer.from(a[0]), Buffer.from(b[0]));
}

// A name that starts with a backslash is a control sequence, keyed without it.
function split(mode) {
  const chars = [];
  const controls = [];
  for (const [name, info] of Object.entries(symbols[mode])) {
    const group = GROUPS[info.group];
    const font = FONTS[info.font];
    if (!group || !font || typeof info.replace !== "string") {
      throw new Error(`unexpected symbol ${JSON.stringify([name, info])}`);
    }
    const entry = [name.startsWith("\\") ? name.slice(1) : name, font, group, info.replace];
    (name.startsWith("\\") ? controls : chars).push(entry);
  }
  chars.sort(byBytes);
  controls.sort(byBytes);
  return { chars, controls };
}

function table(name, entries) {
  const rows = entries
    .map(([key, font, group, replace]) =>
      `    (${rustString(key)}, Font::${font}, AtomGroup::${group}, ${rustString(replace)}),`)
    .join("\n");
  return `pub(super) static ${name}: &[Entry] = &[\n${rows}\n];\n`;
}

const math = split("math");
const text = split("text");

const out = `// GENERATED by scripts/katex-symbols.mjs from KaTeX's src/symbols.ts (v0.19.1). Do not edit:
// change the script and run it again. Adapted from KaTeX, MIT licensed, Copyright (c) 2013-2020
// Khan Academy and other contributors; see THIRD-PARTY-NOTICES.
//
// Each entry is a command or character, the font its glyph comes from, its TeX atom group, and
// the text to draw. Control sequences are keyed without their backslash. Every slice is sorted
// by the bytes of its key, and a test checks it.

use super::symbols::{AtomGroup, Entry, Font};

${table("MATH_CHARS", math.chars)}
${table("MATH_CONTROLS", math.controls)}
${table("TEXT_CHARS", text.chars)}
${table("TEXT_CONTROLS", text.controls)}`;

writeFileSync(new URL("../crates/sirene-core/src/math/symbols_data.rs", import.meta.url), out);
console.log(
  `math: ${math.chars.length} characters, ${math.controls.length} controls; ` +
    `text: ${text.chars.length} characters, ${text.controls.length} controls`,
);
